  1018      for (i = 0; i < h; i++) {
  1019          linet = datat + i * wplt;
  1020          lined = datad + i * wpld;
  1021          for (j = 0; j < w; j++) {
  1022              extractRGBValues(linet[j], &rval, &gval, &bval);
  1023              minrg = L_MIN(rval, gval);
  1024              min = L_MIN(minrg, bval);
  1025              maxrg = L_MAX(rval, gval);
  1026              max = L_MAX(maxrg, bval);
  1027              delta = max - min;
  1028              if (delta == 0)  /* gray; no chroma */
  1029                  sval = 0;
  1030              else
  1031                  sval = (l_int32)(255. * (l_float32)delta * invmax[max] + 0.5);
