  1033              fullsat = L_MIN(255, 255 * ratio[max]);
  1034              newval = (sval * fullsat + (255 - sval) * max) / 255;
  1035              SET_DATA_BYTE(lined, j, newval);
  1036          }
  1037      }
  1038
  1039      pixDestroy(&pixt);
  1040      LEPT_FREE(invmax);
  1041      LEPT_FREE(ratio);
  1042      return pixd;
  1043  }
