  1426  NUMA    *na;
  1427  PIX     *pixd;
  1428
  1429      PROCNAME("pixConvertRGBToColormap");
  1430
  1431      if (!pixs)
  1432          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  1433      if (pixGetDepth(pixs) != 32)
  1434          return (PIX *)ERROR_PTR("pixs not 32 bpp", procName, NULL);
  1435      if (pixGetSpp(pixs) == 4)
  1436          L_WARNING("pixs has alpha; removing\n", procName);
  1437
  1438          /* Get the histogram and count the number of occupied level 4
  1439           * leaf octcubes.  We don't yet know if this is the number of
  1440           * actual colors, but if it's not, all pixels falling into
  1441           * the same leaf octcube will be assigned to the color of the
  1442           * first pixel that lands there. */
  1443      na = pixOctcubeHistogram(pixs, 4, &ncolors);
  1444
  1445          /* If there are too many occupied leaf octcubes to be
  1446           * represented directly in a colormap, fall back to octree
  1447           * quantization, optionally with dithering. */
  1448      if (ncolors > 256) {
  1449          numaDestroy(&na);
  1450          if (ditherflag)
  1451              L_INFO("More than 256 colors; using octree quant with dithering\n",
  1452                     procName);
