  2615          }
  2616          pixSetColormap(pixd, cmapd);
  2617          for (i = 0; i < h; i++) {
  2618              lines = datas + i * wpls;
  2619              lined = datad + i * wpld;
  2620              for (j = 0; j < w; j++) {
  2621                  qbit = GET_DATA_QBIT(lines, j);
  2622                  SET_DATA_BYTE(lined, j, qbit);
  2623              }
  2624          }
  2625          return pixd;
  2626      }
  2627
  2628          /* Last case: no colormap in either pixs or pixd.
  2629           * Replicate the qbit value into 8 bits. */
  2630      for (i = 0; i < h; i++) {
  2631          lines = datas + i * wpls;
  2632          lined = datad + i * wpld;
  2633          for (j = 0; j < w; j++) {
  2634              qbit = GET_DATA_QBIT(lines, j);
  2635              byte = (qbit << 4) | qbit;
  2636              SET_DATA_BYTE(lined, j, byte);
  2637          }
  2638      }
  2639      return pixd;
  2640  }
