  2644  /*---------------------------------------------------------------------------*
  2645   *               Unpacking conversion from 8 bpp to 16 bpp                   *
  2646   *---------------------------------------------------------------------------*/
  2647  /*!
  2648   * \brief   pixConvert8To16()
  2649   *
  2650   * \param[in]    pixs       8 bpp; colormap removed to gray
  2651   * \param[in]    leftshift  number of bits: 0 is no shift;
  2652   *                          8 replicates in MSB and LSB of dest
  2653   * \return  pixd 16 bpp, or NULL on error
  2654   *
  2655   * <pre>
  2656   * Notes:
  2657   *      (1) For left shift of 8, the 8 bit value is replicated in both
  2658   *          the MSB and the LSB of the pixels in pixd.  That way, we get
  2659   *          proportional mapping, with a correct map from 8 bpp white
  2660   *          (0xff) to 16 bpp white (0xffff).
  2661   * </pre>
  2662   */
  2663  PIX *
  2664  pixConvert8To16(PIX     *pixs,
  2665                  l_int32  leftshift)
  2666  {
  2667  l_int32    i, j, w, h, d, wplt, wpld, val;
  2668  l_uint32  *datat, *datad, *linet, *lined;
  2669  PIX       *pixt, *pixd;
  2670
  2671      PROCNAME("pixConvert8To16");
  2672
  2673      if (!pixs)
  2674          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  2675      pixGetDimensions(pixs, &w, &h, &d);
  2676      if (d != 8)
  2677          return (PIX *)ERROR_PTR("pixs not 8 bpp", procName, NULL);
  2678      if (leftshift < 0 || leftshift > 8)
  2679          return (PIX *)ERROR_PTR("leftshift not in [0 ... 8]", procName, NULL);
  2680
  2681      if (pixGetColormap(pixs) != NULL)
  2682          pixt = pixRemoveColormap(pixs, REMOVE_CMAP_TO_GRAYSCALE);
  2683      else
  2684          pixt = pixClone(pixs);
  2685
  2686      pixd = pixCreate(w, h, 16);
  2687      pixCopyResolution(pixd, pixs);
  2688      pixCopyInputFormat(pixd, pixs);
  2689      datat = pixGetData(pixt);
  2690      datad = pixGetData(pixd);
  2691      wplt = pixGetWpl(pixt);
  2692      wpld = pixGetWpl(pixd);
  2693      for (i = 0; i < h; i++) {
  2694          linet = datat + i * wplt;
  2695          lined = datad + i * wpld;
  2696          for (j = 0; j < w; j++) {
  2697              val = GET_DATA_BYTE(linet, j);
  2698              if (leftshift == 8)
  2699                  val = val | (val << leftshift);
  2700              else
  2701                  val <<= leftshift;
  2702              SET_DATA_TWO_BYTES(lined, j, val);
  2703          }
  2704      }
  2705
  2706      pixDestroy(&pixt);
  2707      return pixd;
  2708  }
