  2717   * \param[in]    pixs   1, 2, 4, 8, 32 bpp; colormap OK but will be removed
  2718   * \return  pixd   2 bpp, or NULL on error
  2719   *
  2720   * <pre>
  2721   * Notes:
  2722   *      (1) This is a top-level function, with simple default values
  2723   *          used in pixConvertTo8() if unpacking is necessary.
  2724   *      (2) Any existing colormap is removed; the result is always gray.
  2725   *      (3) If the input image has 2 bpp and no colormap, the operation is
  2726   *          lossless and a copy is returned.
  2727   * </pre>
  2728   */
  2729  PIX *
  2730  pixConvertTo2(PIX  *pixs)
  2731  {
  2732  l_int32  d;
  2733  PIX     *pix1, *pix2, *pix3, *pixd;
  2734
  2735      PROCNAME("pixConvertTo2");
  2736
  2737      if (!pixs)
  2738          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  2739      d = pixGetDepth(pixs);
  2740      if (d != 1 && d != 2 && d != 4 && d != 8 && d != 32)
  2741          return (PIX *)ERROR_PTR("depth not {1,2,4,8,32}", procName, NULL);
  2742
  2743      if (pixGetColormap(pixs) != NULL) {
  2744          pix1 = pixRemoveColormap(pixs, REMOVE_CMAP_TO_GRAYSCALE);
  2745          d = pixGetDepth(pix1);
  2746      } else {
  2747          pix1 = pixCopy(NULL, pixs);
  2748      }
  2749      if (d == 32)
  2750          pix2 = pixConvertTo8(pix1, FALSE);
  2751      else
  2752          pix2 = pixClone(pix1);
  2753      pixDestroy(&pix1);
  2754      if (d == 1) {
  2755          pixd = pixConvert1To2(NULL, pix2, 3, 0);
  2756      } else if (d == 2) {
  2757          pixd = pixClone(pix2);
  2758      } else if (d == 4) {
  2759          pix3 = pixConvert4To8(pix2, FALSE);  /* unpack to 8 */
  2760          pixd = pixConvert8To2(pix3);
  2761          pixDestroy(&pix3);
  2762      } else {  /* d == 8 */
  2763          pixd = pixConvert8To2(pix2);
  2764      }
  2765      pixDestroy(&pix2);
  2766      return pixd;
  2767  }
