  3405      if (pixGetColormap(pixs))
  3406          return pixRemoveColormap(pixs, REMOVE_CMAP_TO_FULL_COLOR);
  3407
  3408      pixGetDimensions(pixs, &w, &h, NULL);
  3409      datas = pixGetData(pixs);
  3410      wpls = pixGetWpl(pixs);
  3411      if ((pixd = pixCreate(w, h, 32)) == NULL)
  3412          return (PIX *)ERROR_PTR("pixd not made", procName, NULL);
  3413      pixCopyResolution(pixd, pixs);
  3414      pixCopyInputFormat(pixd, pixs);
  3415      datad = pixGetData(pixd);
  3416      wpld = pixGetWpl(pixd);
  3417
  3418          /* Replication table gray --> rgb */
  3419      tab = (l_uint32 *)LEPT_CALLOC(256, sizeof(l_uint32));
  3420      for (i = 0; i < 256; i++)
  3421        tab[i] = (i << 24) | (i << 16) | (i << 8);
  3422
  3423          /* Replicate 1 --> 4 bytes (alpha byte not set) */
  3424      for (i = 0; i < h; i++) {
  3425          lines = datas + i * wpls;
  3426          lined = datad + i * wpld;
  3427          for (j = 0; j < w; j++) {
  3428              val = GET_DATA_BYTE(lines, j);
  3429              lined[j] = tab[val];
  3430          }
  3431      }
  3432
  3433      LEPT_FREE(tab);
  3434      return pixd;
  3435  }
