  3447   * \param[in]    warnflag  1 to issue warning if colormap is removed; else 0
  3448   * \return  pixd 8 bpp grayscale or 32 bpp rgb, or NULL on error
  3449   *
  3450   * <pre>
  3451   * Notes:
  3452   *      (1) If there is a colormap, the colormap is removed to 8 or 32 bpp,
  3453   *          depending on whether the colors in the colormap are all gray.
  3454   *      (2) If the input is either rgb or 8 bpp without a colormap,
  3455   *          this returns either a clone or a copy, depending on %copyflag.
  3456   *      (3) Otherwise, the pix is converted to 8 bpp grayscale.
  3457   *          In all cases, pixd does not have a colormap.
  3458   * </pre>
  3459   */
  3460  PIX *
  3461  pixConvertTo8Or32(PIX     *pixs,
  3462                    l_int32  copyflag,
  3463                    l_int32  warnflag)
  3464  {
  3465  l_int32  d;
  3466  PIX     *pixd;
  3467
  3468      PROCNAME("pixConvertTo8Or32");
  3469
  3470      if (!pixs)
  3471          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  3472      if (copyflag != L_CLONE && copyflag != L_COPY)
  3473          return (PIX *)ERROR_PTR("invalid copyflag", procName, NULL);
  3474
  3475      d = pixGetDepth(pixs);
  3476      if (pixGetColormap(pixs)) {
  3477          if (warnflag) L_WARNING("pix has colormap; removing\n", procName);
  3478          pixd = pixRemoveColormap(pixs, REMOVE_CMAP_BASED_ON_SRC);
  3479      } else if (d == 8 || d == 32) {
  3480          if (copyflag == L_CLONE)
  3481              pixd = pixClone(pixs);
  3482          else  /* copyflag == L_COPY */
  3483              pixd = pixCopy(NULL, pixs);
  3484      } else {
  3485          pixd = pixConvertTo8(pixs, 0);
  3486      }
  3487
  3488          /* Sanity check on result */
  3489      d = pixGetDepth(pixd);
  3490      if (d != 8 && d != 32) {
  3491          pixDestroy(&pixd);
  3492          return (PIX *)ERROR_PTR("depth not 8 or 32 bpp", procName, NULL);
  3493      }
  3494
  3495      return pixd;
  3496  }
