  3948   *---------------------------------------------------------------------------*/
  3949  /*!
  3950   * \brief   pixConvertToSubpixelRGB()
  3951   *
  3952   * \param[in]    pixs            8 bpp grayscale, 32 bpp rgb, or colormapped
  3953   * \param[in]    scalex, scaley  anisotropic scaling permitted between
  3954   *                               source and destination
  3955   * \param[in]    order           of subpixel rgb color components in
  3956   *                               composition of pixd:
  3957   *                               L_SUBPIXEL_ORDER_RGB, L_SUBPIXEL_ORDER_BGR,
  3958   *                               L_SUBPIXEL_ORDER_VRGB, L_SUBPIXEL_ORDER_VBGR
  3959   * \return  pixd 32 bpp, or NULL on error
  3960   *
  3961   * <pre>
  3962   * Notes:
  3963   *      (1) If pixs has a colormap, it is removed based on its contents
  3964   *          to either 8 bpp gray or rgb.
  3965   *      (2) For horizontal subpixel splitting, the input image
  3966   *          is rescaled by %scaley vertically and by 3.0 times
  3967   *          %scalex horizontally.  Then each horizontal triplet
  3968   *          of pixels is mapped back to a single rgb pixel, with the
  3969   *          r, g and b values being assigned based on the pixel triplet.
  3970   *          For gray triplets, the r, g, and b values are set equal to
  3971   *          the three gray values.  For color triplets, the r, g and b
  3972   *          values are set equal to the components from the appropriate
  3973   *          subpixel.  Vertical subpixel splitting is handled similarly.
  3974   *      (3) See pixConvertGrayToSubpixelRGB() and
  3975   *          pixConvertColorToSubpixelRGB() for further details.
  3976   * </pre>
  3977   */
  3978  PIX *
  3979  pixConvertToSubpixelRGB(PIX       *pixs,
  3980                          l_float32  scalex,
  3981                          l_float32  scaley,
  3982                          l_int32    order)
  3983  {
  3984  l_int32    d;
  3985  PIX       *pix1, *pixd;
  3986  PIXCMAP   *cmap;
  3987
  3988      PROCNAME("pixConvertToSubpixelRGB");
  3989
  3990      if (!pixs)
  3991          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  3992      d = pixGetDepth(pixs);
  3993      cmap = pixGetColormap(pixs);
  3994      if (d != 8 && d != 32 && !cmap)
  3995          return (PIX *)ERROR_PTR("pix not 8 or 32 bpp and not cmapped",
  3996                                  procName, NULL);
  3997      if (scalex <= 0.0 || scaley <= 0.0)
  3998          return (PIX *)ERROR_PTR("scale factors must be > 0", procName, NULL);
  3999      if (order != L_SUBPIXEL_ORDER_RGB && order != L_SUBPIXEL_ORDER_BGR &&
  4000          order != L_SUBPIXEL_ORDER_VRGB && order != L_SUBPIXEL_ORDER_VBGR)
  4001          return (PIX *)ERROR_PTR("invalid subpixel order", procName, NULL);
  4002      if ((pix1 = pixRemoveColormap(pixs, REMOVE_CMAP_BASED_ON_SRC)) == NULL)
  4003          return (PIX *)ERROR_PTR("pix1 not made", procName, NULL);
  4004
  4005      d = pixGetDepth(pix1);
  4006      pixd = NULL;
  4007      if (d == 8)
  4008          pixd = pixConvertGrayToSubpixelRGB(pix1, scalex, scaley, order);
  4009      else if (d == 32)
  4010          pixd = pixConvertColorToSubpixelRGB(pix1, scalex, scaley, order);
  4011      else
  4012          L_ERROR("invalid depth %d\n", procName, d);
  4013
  4014      pixDestroy(&pix1);
  4015      return pixd;
  4016  }
