  4019  /*!
  4020   * \brief   pixConvertGrayToSubpixelRGB()
  4021   *
  4022   * \param[in]    pixs            8 bpp or colormapped
  4023   * \param[in]    scalex, scaley
  4024   * \param[in]    order           of subpixel rgb color components in
  4025   *                               composition of pixd:
  4026   *                               L_SUBPIXEL_ORDER_RGB, L_SUBPIXEL_ORDER_BGR,
  4027   *                               L_SUBPIXEL_ORDER_VRGB, L_SUBPIXEL_ORDER_VBGR
  4028   * \return  pixd 32 bpp, or NULL on error
  4029   *
  4030   * <pre>
  4031   * Notes:
  4032   *      (1) If pixs has a colormap, it is removed to 8 bpp.
  4033   *      (2) For horizontal subpixel splitting, the input gray image
  4034   *          is rescaled by %scaley vertically and by 3.0 times
  4035   *          %scalex horizontally.  Then each horizontal triplet
  4036   *          of pixels is mapped back to a single rgb pixel, with the
  4037   *          r, g and b values being assigned from the triplet of gray values.
  4038   *          Similar operations are used for vertical subpixel splitting.
  4039   *      (3) This is a form of subpixel rendering that tends to give the
  4040   *          resulting text a sharper and somewhat chromatic display.
  4041   *          For horizontal subpixel splitting, the observable difference
  4042   *          between %order=L_SUBPIXEL_ORDER_RGB and
  4043   *          %order=L_SUBPIXEL_ORDER_BGR is reduced by optical diffusers
  4044   *          in the display that make the pixel color appear to emerge
  4045   *          from the entire pixel.
  4046   * </pre>
  4047   */
  4048  PIX *
  4049  pixConvertGrayToSubpixelRGB(PIX       *pixs,
  4050                              l_float32  scalex,
  4051                              l_float32  scaley,
  4052                              l_int32    order)
  4053  {
  4054  l_int32    w, h, d, wd, hd, wplt, wpld, i, j, rval, gval, bval, direction;
  4055  l_uint32  *datat, *datad, *linet, *lined;
  4056  PIX       *pix1, *pix2, *pixd;
  4057  PIXCMAP   *cmap;
  4058
  4059      PROCNAME("pixConvertGrayToSubpixelRGB");
  4060
  4061      if (!pixs)
  4062          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
  4063      d = pixGetDepth(pixs);
  4064      cmap = pixGetColormap(pixs);
  4065      if (d != 8 && !cmap)
  4066          return (PIX *)ERROR_PTR("pix not 8 bpp & not cmapped", procName, NULL);
  4067      if (scalex <= 0.0 || scaley <= 0.0)
  4068          return (PIX *)ERROR_PTR("scale factors must be > 0", procName, NULL);
  4069      if (order != L_SUBPIXEL_ORDER_RGB && order != L_SUBPIXEL_ORDER_BGR &&
  4070          order != L_SUBPIXEL_ORDER_VRGB && order != L_SUBPIXEL_ORDER_VBGR)
  4071          return (PIX *)ERROR_PTR("invalid subpixel order", procName, NULL);
  4072
  4073      direction =
  4074          (order == L_SUBPIXEL_ORDER_RGB || order == L_SUBPIXEL_ORDER_BGR)
  4075          ? L_HORIZ : L_VERT;
  4076      pix1 = pixRemoveColormap(pixs, REMOVE_CMAP_TO_GRAYSCALE);
  4077      if (direction == L_HORIZ)
  4078          pix2 = pixScale(pix1, 3.0 * scalex, scaley);
  4079      else  /* L_VERT */
  4080          pix2 = pixScale(pix1, scalex, 3.0 * scaley);
  4081
  4082      pixGetDimensions(pix2, &w, &h, NULL);
  4083      wd = (direction == L_HORIZ) ? w / 3 : w;
  4084      hd = (direction == L_VERT) ? h / 3 : h;
  4085      pixd = pixCreate(wd, hd, 32);
  4086      datad = pixGetData(pixd);
  4087      wpld = pixGetWpl(pixd);
  4088      datat = pixGetData(pix2);
  4089      wplt = pixGetWpl(pix2);
  4090      if (direction == L_HORIZ) {
  4091          for (i = 0; i < hd; i++) {
  4092              linet = datat + i * wplt;
  4093              lined = datad + i * wpld;
  4094              for (j = 0; j < wd; j++) {
  4095                  rval = GET_DATA_BYTE(linet, 3 * j);
  4096                  gval = GET_DATA_BYTE(linet, 3 * j + 1);
  4097                  bval = GET_DATA_BYTE(linet, 3 * j + 2);
  4098                  if (order == L_SUBPIXEL_ORDER_RGB)
  4099                      composeRGBPixel(rval, gval, bval, &lined[j]);
  4100                  else  /* order BGR */
  4101                      composeRGBPixel(bval, gval, rval, &lined[j]);
  4102              }
  4103          }
  4104      } else {  /* L_VERT */
  4105          for (i = 0; i < hd; i++) {
  4106              linet = datat + 3 * i * wplt;
  4107              lined = datad + i * wpld;
  4108              for (j = 0; j < wd; j++) {
  4109                  rval = GET_DATA_BYTE(linet, j);
  4110                  gval = GET_DATA_BYTE(linet + wplt, j);
  4111                  bval = GET_DATA_BYTE(linet + 2 * wplt, j);
  4112                  if (order == L_SUBPIXEL_ORDER_VRGB)
  4113                      composeRGBPixel(rval, gval, bval, &lined[j]);
  4114                  else  /* order VBGR */
  4115                      composeRGBPixel(bval, gval, rval, &lined[j]);
  4116              }
  4117          }
  4118      }
  4119
  4120      pixDestroy(&pix1);
  4121      pixDestroy(&pix2);
  4122      return pixd;
  4123  }
