  4206                      extractRGBValues(linet[3 * j], NULL, NULL, &bval);
  4207                      extractRGBValues(linet[3 * j + 1], NULL, &gval, NULL);
  4208                      extractRGBValues(linet[3 * j + 2], &rval, NULL, NULL);
  4209                  }
  4210                  composeRGBPixel(rval, gval, bval, &lined[j]);
  4211              }
  4212          }
  4213      } else {  /* L_VERT */
  4214          for (i = 0; i < hd; i++) {
  4215              linet = datat + 3 * i * wplt;
  4216              lined = datad + i * wpld;
  4217              for (j = 0; j < wd; j++) {
  4218                  if (order == L_SUBPIXEL_ORDER_VRGB) {
  4219                      extractRGBValues(linet[j], &rval, NULL, NULL);
  4220                      extractRGBValues((linet + wplt)[j], NULL, &gval, NULL);
  4221                      extractRGBValues((linet + 2 * wplt)[j], NULL, NULL, &bval);
  4222                  } else {  /* order VBGR */
  4223                      extractRGBValues(linet[j], NULL, NULL, &bval);
  4224                      extractRGBValues((linet + wplt)[j], NULL, &gval, NULL);
  4225                      extractRGBValues((linet + 2 * wplt)[j], &rval, NULL, NULL);
  4226                  }
  4227                  composeRGBPixel(rval, gval, bval, &lined[j]);
  4228              }
  4229          }
  4230      }
  4231
  4232      if (pixGetSpp(pixs) == 4)
  4233          pixScaleAndTransferAlpha(pixd, pixs, scalex, scaley);
  4234
  4235      pixDestroy(&pix1);
  4236      pixDestroy(&pix2);
  4237      return pixd;
  4238  }
